do $$
declare w uuid=gen_random_uuid();u uuid=gen_random_uuid();c uuid=gen_random_uuid();a uuid=gen_random_uuid();f uuid=gen_random_uuid(); failed boolean=false; rule salon_benefit_settings; sid uuid=gen_random_uuid(); gid uuid=gen_random_uuid(); b uuid=gen_random_uuid(); cat service_package_catalog; pack customer_service_packages; rid uuid;
begin
 insert into auth.users(id,email) values(u,u||'@example.invalid');
 insert into workspaces(id,salon_name,slug,owner_email,subscription_status,subscription_ends_at) values(w,'Completion fixture','completion-'||w,u||'@example.invalid','active',now()+interval '1 year');
 insert into workspace_members(workspace_id,user_id,email) values(w,u,u||'@example.invalid');
 perform set_config('request.jwt.claim.sub',u::text,true);
 insert into customers(id,workspace_id,full_name,phone) values(c,w,'Completion fixture','390000000001');
 rule=save_salon_benefit_settings(false,true,false,1,1);
 rule=save_loyalty_earning_rule(rule.revision,'service',1,500,1,true,true,true,0,'');
 insert into appointments(id,workspace_id,customer_id,appointment_date,appointment_time,customer_name,service_name,price,duration_minutes) values(a,w,c,(now() at time zone 'Europe/Rome')::date,'10:00','Completion fixture','Service',0,30),(f,w,c,current_date+10,'10:00','Completion fixture','Future',12,30);
 perform complete_owner_appointment_v1(a,w);
 set constraints all immediate;
 if not (select completed and not cashed_in from appointments where id=a) then raise exception 'TEST completion or payment state incorrect'; end if;
 if exists(select 1 from cash_movements where workspace_id=w) then raise exception 'TEST completion created income'; end if;
 if (select sum(delta) from customer_loyalty_ledger where customer_id=c) is distinct from 1::bigint then raise exception 'TEST service points missing'; end if;
 perform complete_owner_appointment_v1(a,w);
 if (select sum(delta) from customer_loyalty_ledger where customer_id=c)<>1 then raise exception 'TEST duplicate points'; end if;
 begin perform complete_owner_appointment_v1(f,w); exception when others then failed=true; end;
 if not failed then raise exception 'TEST future completion accepted'; end if;
 rule=save_salon_benefit_settings(true,true,false,1,rule.revision);
 insert into services(id,workspace_id,name,price,duration_minutes) values(sid,w,'Package service',12,30);
 cat=save_service_package(null,0,'Completion package',jsonb_build_array(jsonb_build_object('kind','service','id',sid)),3,3,3000,0);
 pack=assign_service_package(gen_random_uuid(),c,cat.id,cat.revision,current_date,'cash');
 a=gen_random_uuid();
 insert into appointments(id,workspace_id,customer_id,appointment_date,appointment_time,customer_name,service_name,price,duration_minutes) values(a,w,c,current_date,'12:00','Completion fixture','Package service',12,30);
 rid=apply_owner_service_package(pack.id,a);
 perform complete_owner_appointment_v1(a,w);
 if (select state from service_package_redemptions where id=rid)<>'consumed' then raise exception 'TEST package not consumed'; end if;
 perform complete_owner_appointment_v1(a,w);
 if (select count(*) from service_package_redemptions where package_id=pack.id)<>1 then raise exception 'TEST package consumed twice'; end if;
 insert into appointment_groups(id,workspace_id,customer_id,title,source) values(gid,w,c,'Completion group','salon');
 a=gen_random_uuid();
 insert into appointments(id,workspace_id,customer_id,appointment_date,appointment_time,customer_name,service_name,price,duration_minutes,appointment_group_id) values(a,w,c,current_date,'13:00','Completion fixture','Phase 1',12,30,gid),(b,w,c,current_date,'13:30','Completion fixture','Phase 2',12,30,gid);
 perform complete_owner_appointment_v1(a,w);
 if exists(select 1 from appointments where appointment_group_id=gid and (not completed or cashed_in)) then raise exception 'TEST group completion incorrect'; end if;
 if (select count(*) from customer_loyalty_ledger where reference_key='service:'||gid)<>1 then raise exception 'TEST group points duplicated'; end if;
 failed=false;
 begin perform complete_owner_appointment_v1(a,gen_random_uuid()); exception when others then failed=true; end;
 if not failed then raise exception 'TEST wrong workspace accepted'; end if;
end $$;
